rust.code:
pub fn badge(ui: &mut Container) {
    ui.row(Row::new().size(1).gap(1), |r| {
        r.badge(BadgeOptions::new("active"));
        r.badge(BadgeOptions::new("idle").variant(BadgeVariant::Subtle));
        r.badge(BadgeOptions::new("failed").variant(BadgeVariant::Outline));
        r.spacer("fill");
    });
}

go.code:
func Badge(ui *hqtui.Container) {
	ui.Row(hqtui.RowOptions{Layout: hqtui.Layout{Size: size(hqtui.Cells(1)), Gap: 1}}, func(r *hqtui.Container) {
		r.Badge(hqtui.BadgeOptions{Text: "active"})
		r.Badge(hqtui.BadgeOptions{Text: "idle", Variant: hqtui.BadgeSubtle})
		r.Badge(hqtui.BadgeOptions{Text: "failed", Variant: hqtui.BadgeOutline})
		r.Spacer(hqtui.Fill())
	})
}

zig.code:
fn badge(ui: *Container) anyerror!void {
    try ui.row(.{ .layout = .{ .size = .{ .cells = 1 }, .gap = 1 } }, hqtui.Body.plain(badgeRow));
}

fn badgeRow(r: *Container) anyerror!void {
    _ = try r.badge(.{ .text = "active" });
    _ = try r.badge(.{ .text = "idle", .variant = .subtle });
    _ = try r.badge(.{ .text = "failed", .variant = .outline });
    try r.spacer(.fill);
}

